    if (items.length >= 3) return { template: 'list', headline: clipW(lines.find(l => !bullet.test(l)) || '', 80), items: items.slice(0, 6).map(i => clipW(i, 80)), why: `${items.length} points. Lists get saved, and saves travel.` };
    /* 4. one big number */
